\echo '=== B. SiteName present in more than one source (Files) - main overlap signal ==='
SELECT "SiteName", string_agg(source_db, ', ' ORDER BY source_db) AS sources
FROM (
SELECT DISTINCT 'cwp_ecr' AS source_db, "SiteName" FROM "src_cwp_ecr"."Files"
UNION ALL SELECT DISTINCT 'cwp_opspj3' AS source_db, "SiteName" FROM "src_cwp_opspj3"."Files"
UNION ALL SELECT DISTINCT 'cwp_opspj' AS source_db, "SiteName" FROM "src_cwp_opspj"."Files"
UNION ALL SELECT DISTINCT 'cwp_procon' AS source_db, "SiteName" FROM "src_cwp_procon"."Files"
UNION ALL SELECT DISTINCT 'cwp_opspj2' AS source_db, "SiteName" FROM "src_cwp_opspj2"."Files"
UNION ALL SELECT DISTINCT 'cwp_opspj4' AS source_db, "SiteName" FROM "src_cwp_opspj4"."Files"
UNION ALL SELECT DISTINCT 'cwp_xrl' AS source_db, "SiteName" FROM "src_cwp_xrl"."Files"
UNION ALL SELECT DISTINCT 'cwp' AS source_db, "SiteName" FROM "src_cwp"."Files"
UNION ALL SELECT DISTINCT 'cwp2' AS source_db, "SiteName" FROM "src_cwp2"."Files"
) x GROUP BY "SiteName" HAVING COUNT(*) > 1 ORDER BY 1;

\echo '=== C. Files.OriginalSharePointPath overlaps (lower_priority rows will be SKIPPED with their Metadata/Permissions/Tasks) ==='
WITH k AS (
SELECT 'cwp_ecr' AS source_db, "OriginalSharePointPath" AS k FROM "src_cwp_ecr"."Files"
UNION ALL SELECT 'cwp_opspj3' AS source_db, "OriginalSharePointPath" AS k FROM "src_cwp_opspj3"."Files"
UNION ALL SELECT 'cwp_opspj' AS source_db, "OriginalSharePointPath" AS k FROM "src_cwp_opspj"."Files"
UNION ALL SELECT 'cwp_procon' AS source_db, "OriginalSharePointPath" AS k FROM "src_cwp_procon"."Files"
UNION ALL SELECT 'cwp_opspj2' AS source_db, "OriginalSharePointPath" AS k FROM "src_cwp_opspj2"."Files"
UNION ALL SELECT 'cwp_opspj4' AS source_db, "OriginalSharePointPath" AS k FROM "src_cwp_opspj4"."Files"
UNION ALL SELECT 'cwp_xrl' AS source_db, "OriginalSharePointPath" AS k FROM "src_cwp_xrl"."Files"
UNION ALL SELECT 'cwp' AS source_db, "OriginalSharePointPath" AS k FROM "src_cwp"."Files"
UNION ALL SELECT 'cwp2' AS source_db, "OriginalSharePointPath" AS k FROM "src_cwp2"."Files"
)
SELECT a.source_db AS higher_priority, b.source_db AS lower_priority, COUNT(*) AS overlapping_keys
FROM k a JOIN k b ON a.k = b.k JOIN _merge.source sa ON sa.source_db = a.source_db
JOIN _merge.source sb ON sb.source_db = b.source_db AND sb.load_order > sa.load_order
GROUP BY 1, 2 ORDER BY 1, 2;

\echo '=== D. ADGroups.GroupName overlaps (will be MERGED; members re-pointed) ==='
WITH k AS (
SELECT 'cwp_ecr' AS source_db, "GroupName" AS k FROM "src_cwp_ecr"."ADGroups"
UNION ALL SELECT 'cwp_opspj3' AS source_db, "GroupName" AS k FROM "src_cwp_opspj3"."ADGroups"
UNION ALL SELECT 'cwp_opspj' AS source_db, "GroupName" AS k FROM "src_cwp_opspj"."ADGroups"
UNION ALL SELECT 'cwp_procon' AS source_db, "GroupName" AS k FROM "src_cwp_procon"."ADGroups"
UNION ALL SELECT 'cwp_opspj2' AS source_db, "GroupName" AS k FROM "src_cwp_opspj2"."ADGroups"
UNION ALL SELECT 'cwp_opspj4' AS source_db, "GroupName" AS k FROM "src_cwp_opspj4"."ADGroups"
UNION ALL SELECT 'cwp_xrl' AS source_db, "GroupName" AS k FROM "src_cwp_xrl"."ADGroups"
UNION ALL SELECT 'cwp' AS source_db, "GroupName" AS k FROM "src_cwp"."ADGroups"
UNION ALL SELECT 'cwp2' AS source_db, "GroupName" AS k FROM "src_cwp2"."ADGroups"
)
SELECT a.source_db AS higher_priority, b.source_db AS lower_priority, COUNT(*) AS overlapping_keys
FROM k a JOIN k b ON a.k = b.k JOIN _merge.source sa ON sa.source_db = a.source_db
JOIN _merge.source sb ON sb.source_db = b.source_db AND sb.load_order > sa.load_order
GROUP BY 1, 2 ORDER BY 1, 2;

\echo '=== E. ScanProgress (LibraryName, SiteName) overlaps (lower_priority rows SKIPPED) ==='
