\echo '=== H. Projected ID ranges (must stay <= 2147483647) ==='
SELECT domain, source_db, id_offset + 1 AS first_new_id, id_offset + src_max_id AS last_new_id,
       CASE WHEN id_offset + src_max_id > 2147483647 THEN 'OVERFLOW' ELSE 'ok' END AS status
FROM (
SELECT 'Files', src, COALESCE(SUM(mx) OVER (ORDER BY ord ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING), 0), mx
FROM (VALUES
    ('cwp_ecr', 1, COALESCE(GREATEST((SELECT MAX("FileId") FROM "src_cwp_ecr"."Files"), (SELECT MAX("FileId") FROM "src_cwp_ecr"."MigrationTasks_Parsed"), (SELECT MAX("LastResolvedFileId") FROM "src_cwp_ecr"."ScanProgress")), 0)::bigint),
    ('cwp_opspj3', 2, COALESCE(GREATEST((SELECT MAX("FileId") FROM "src_cwp_opspj3"."Files"), (SELECT MAX("FileId") FROM "src_cwp_opspj3"."MigrationTasks_Parsed"), (SELECT MAX("LastResolvedFileId") FROM "src_cwp_opspj3"."ScanProgress")), 0)::bigint),
    ('cwp_opspj', 3, COALESCE(GREATEST((SELECT MAX("FileId") FROM "src_cwp_opspj"."Files"), (SELECT MAX("FileId") FROM "src_cwp_opspj"."MigrationTasks_Parsed"), (SELECT MAX("LastResolvedFileId") FROM "src_cwp_opspj"."ScanProgress")), 0)::bigint),
    ('cwp_procon', 4, COALESCE(GREATEST((SELECT MAX("FileId") FROM "src_cwp_procon"."Files"), (SELECT MAX("FileId") FROM "src_cwp_procon"."MigrationTasks_Parsed"), (SELECT MAX("LastResolvedFileId") FROM "src_cwp_procon"."ScanProgress")), 0)::bigint),
    ('cwp_opspj2', 5, COALESCE(GREATEST((SELECT MAX("FileId") FROM "src_cwp_opspj2"."Files"), (SELECT MAX("FileId") FROM "src_cwp_opspj2"."MigrationTasks_Parsed"), (SELECT MAX("LastResolvedFileId") FROM "src_cwp_opspj2"."ScanProgress")), 0)::bigint),
    ('cwp_opspj4', 6, COALESCE(GREATEST((SELECT MAX("FileId") FROM "src_cwp_opspj4"."Files"), (SELECT MAX("FileId") FROM "src_cwp_opspj4"."MigrationTasks_Parsed"), (SELECT MAX("LastResolvedFileId") FROM "src_cwp_opspj4"."ScanProgress")), 0)::bigint),
    ('cwp_xrl', 7, COALESCE(GREATEST((SELECT MAX("FileId") FROM "src_cwp_xrl"."Files"), (SELECT MAX("FileId") FROM "src_cwp_xrl"."MigrationTasks_Parsed")), 0)::bigint),
    ('cwp', 8, COALESCE(GREATEST((SELECT MAX("FileId") FROM "src_cwp"."Files"), (SELECT MAX("FileId") FROM "src_cwp"."MigrationTasks_Parsed")), 0)::bigint),
    ('cwp2', 9, COALESCE((SELECT MAX("FileId") FROM "src_cwp2"."Files"), 0)::bigint)
) v(src, ord, mx)
UNION ALL
